export function renderPosts(n,t){if(!t)return;if(0===n.length)return void(t.innerHTML='<p class="text-muted">Henüz hiç kombin paylaşılmamış.</p>');const e=n.map(n=>`\n    <div class="lk-post-card" data-post-id="${n.postId}">\n      <img src="${n.imageUrl}" alt="Kombin" class="lk-post-img">\n      <a href="detail.html?postId=${n.postId}" class="lk-btn-card-incele">İncele</a>\n    </div>\n  `).join("");t.innerHTML=e}